<?php session_start();if(!isset($_SESSION['siswa'])){header('Location: ../auth/v_login.php?type=siswa');exit;}require_once '../../MODEL/m_aspirasi.php';$data=(new Aspirasi())->getByNis((int)$_SESSION['nis']);?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Aspirasi Saya</title><link rel="stylesheet" href="../../ASSETS/modern.css"></head><body><main><a class="back" href="dasbord_siswa.php">← Dashboard</a><div class="page-head"><div><h1>Aspirasi Saya</h1><p>Daftar laporan yang kamu kirim.</p></div><a class="btn btn-primary" href="v_form_aspirasi.php">＋ Kirim Aspirasi</a></div><div class="table-card"><div class="table-wrap"><table><tr><th>ID</th><th>Kategori</th><th>Status</th><th>Admin</th><th>Feedback</th><th>Aksi</th></tr><?php if(!$data):?><tr><td colspan="6" class="empty">Belum ada aspirasi.</td></tr><?php endif;?><?php foreach($data as $r):?><tr><td><b>#<?=$r['id_aspirasi']?></b></td><td><?=htmlspecialchars($r['ket_kategori'])?></td><td><span class="badge <?=strtolower($r['status'])==='proses'?'badge-proses':(strtolower($r['status'])==='selesai'?'badge-selesai':'badge-menunggu')?>"><?=htmlspecialchars($r['status'])?></span></td><td><?=htmlspecialchars($r['username']??'-')?></td><td><?=htmlspecialchars($r['feedback']??'-')?></td><td><?php if($r['status']==='Menunggu'):?><form method="post" action="../../CONTROLLER/c_aspirasi.php"><input type="hidden" name="id_aspirasi" value="<?=$r['id_aspirasi']?>"><button class="btn btn-danger" name="hapus_aspirasi" onclick="return confirm('Hapus aspirasi ini?')">Hapus</button></form><?php else:?><a class="btn btn-light" href="DetailAspirasi.php?id=<?=$r['id_aspirasi']?>">Detail</a><?php endif;?></td></tr><?php endforeach;?></table></div></div></main></body></html>